--
-- Table structure for table `observations`
--

DROP TABLE IF EXISTS `observations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `observations` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `plant_record_id` bigint unsigned NOT NULL,
  `media_id` bigint unsigned DEFAULT NULL,
  `observed_on` date NOT NULL,
  `body` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `height_cm` decimal(10,2) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `map_pin_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `observations_plant_record_id_foreign` (`plant_record_id`),
  KEY `observations_media_id_foreign` (`media_id`),
  KEY `observations_map_pin_id_foreign` (`map_pin_id`),
  CONSTRAINT `observations_map_pin_id_foreign` FOREIGN KEY (`map_pin_id`) REFERENCES `map_pins` (`id`) ON DELETE SET NULL,
  CONSTRAINT `observations_media_id_foreign` FOREIGN KEY (`media_id`) REFERENCES `media` (`id`) ON DELETE SET NULL,
  CONSTRAINT `observations_plant_record_id_foreign` FOREIGN KEY (`plant_record_id`) REFERENCES `plant_records` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1394 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

